import React, { useRef, useEffect } from 'react';
import { View, StyleSheet, TouchableOpacity, Text, Animated, Dimensions } from 'react-native';
import { createStackNavigator } from '@react-navigation/stack';
import { useNavigation, useRoute } from '@react-navigation/native';
import { LinearGradient } from 'expo-linear-gradient';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';

// Suas telas
import SplashLogoScreen from '../screens/SplashLogoScreen';
import TelaInicio from '../screens/Inicio';
import TelaCriarEscala from '../screens/TelaCriarEscala';
import TelaListaEscalas from '../screens/TelaListaEscalas';
import TelaDetalhesEscala from '../screens/DetalhesEscala';
import RepertoiresScreen from '../screens/Repertorios';
import AdicionarRepertorio from '../screens/AdicionarRepertorio';
import DetalheRepertorio from '../screens/DetalheRepertorio';
import VisualizarArquivo from '../screens/VisualizarArquivo';
import PresencaScreen from '../screens/Presenca'; 
import AvisosScreen from '../screens/Avisos';
import EnsaiosScreen from '../screens/Ensaios';
import TelaAniversariantes from '../screens/Aniversariantes';
import TelaAgenda from '../screens/Agenda';

const { width: LARGURA_TELA } = Dimensions.get('window');
const Stack = createStackNavigator();

// 🎯 Itens no formato da imagem (central destacado)
const ITEMS_BARRA = [
  {
    id: 'inicio',
    rotulo: 'Início',
    rota: 'Inicio',
    icone: <MaterialCommunityIcons name="home" size={28} color="#fff" />,
    principal: true, // Item central elevado
  },
  {
    id: 'avisos',
    rotulo: 'Avisos',
    rota: 'Avisos',
    icone: <MaterialCommunityIcons name="bell-alert-outline" size={22} color="#9CA3AF" />,
  },
  {
    id: 'repertorios',
    rotulo: 'Repertório',
    rota: 'Repertorios',
    icone: <MaterialCommunityIcons name="music-circle-outline" size={22} color="#9CA3AF" />,
  },
  {
    id: 'escalas',
    rotulo: 'Escalas',
    rota: 'Escalas',
    icone: <MaterialCommunityIcons name="calendar-check-outline" size={22} color="#9CA3AF" />,
  },
  {
    id: 'presenca',
    rotulo: 'Presença',
    rota: 'Presenca',
    icone: <MaterialCommunityIcons name="account-check-outline" size={22} color="#9CA3AF" />,
  },
  {
    id: 'ensaios',
    rotulo: 'Ensaios',
    rota: 'Ensaios',
    icone: <MaterialCommunityIcons name="account-group-outline" size={22} color="#9CA3AF" />,
  },
  {
    id: 'aniversariantes',
    rotulo: 'Aniversários',
    rota: 'Aniversariantes',
    icone: <MaterialCommunityIcons name="gift-outline" size={22} color="#9CA3AF" />,
  },
  {
    id: 'agenda',
    rotulo: 'Agenda',
    rota: 'Agenda',
    icone: <MaterialCommunityIcons name="calendar-month-outline" size={22} color="#9CA3AF" />,
  },
];

const COR_DESTAQUE = '#8B5CF6'; // Roxo igual da imagem
const COR_FUNDO = '#17152B';

// Componente da Barra Animada no Formato Curvo
const BarraNavegacaoFixa = () => {
  const navegacao = useNavigation();
  const rotaAtual = useRoute().name;

  // Animações individuais
  const animEscala = useRef(new Animated.Value(1)).current;
  const animPosicao = useRef(new Animated.Value(0)).current;
  const animOpacidade = useRef(new Animated.Value(0)).current;

  // Entrada suave da barra ao sair da tela Splash
  useEffect(() => {
    if (rotaAtual !== 'SplashLogo') {
      Animated.timing(animOpacidade, {
        toValue: 1,
        duration: 400,
        useNativeDriver: true,
      }).start();
    }
  }, [rotaAtual]);

  // Animação ao mudar tela
  useEffect(() => {
    const itemSelecionado = ITEMS_BARRA.find(i => i.rota === rotaAtual);
    Animated.parallel([
      Animated.spring(animEscala, {
        toValue: itemSelecionado?.principal ? 1.1 : 1,
        useNativeDriver: true,
        speed: 50,
        bounciness: 3,
      }),
      Animated.timing(animPosicao, {
        toValue: itemSelecionado?.principal ? -12 : 0,
        duration: 250,
        useNativeDriver: true,
      }),
    ]).start();
  }, [rotaAtual]);

  // NÃO MOSTRA NA TELA DE CARREGAMENTO
  if (rotaAtual === 'SplashLogo') return null;

  return (
    <Animated.View style={[estilos.barraContainer, { opacity: animOpacidade }]}>
      {/* Fundo curvo branco/claro no formato da imagem */}
      <View style={estilos.barraFundo}>
        {/* Recorte curvo para o item central */}
        <View style={estilos.recorteCentral}>
          <LinearGradient
            colors={[COR_DESTAQUE, '#A78BFA']}
            style={estilos.botaoCentral}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
          >
            {ITEMS_BARRA[0].icone}
          </LinearGradient>
        </View>

        {/* Itens laterais */}
        {ITEMS_BARRA.slice(1).map((item, idx) => {
          const selecionado = item.rota === rotaAtual;
          return (
            <TouchableOpacity
              key={item.id}
              style={estilos.itemLateral}
              activeOpacity={0.7}
              onPress={() => navegacao.navigate(item.rota as never)}
            >
              <Animated.View
                style={[
                  estilos.iconeLateral,
                  {
                    transform: [
                      { scale: selecionado ? 1.15 : 1 },
                      { translateY: selecionado ? -3 : 0 },
                    ],
                    opacity: selecionado ? 1 : 0.6,
                  },
                ]}
              >
                {item.icone}
              </Animated.View>
              <Text style={[
                estilos.rotuloLateral,
                { color: selecionado ? COR_DESTAQUE : '#9CA3AF' }
              ]}>
                {item.rotulo}
              </Text>
            </TouchableOpacity>
          );
        })}
      </View>
    </Animated.View>
  );
};

export default function AppNavigator() {
  return (
    <View style={estilos.containerPrincipal}>
      <View style={estilos.areaConteudo}>
        <Stack.Navigator initialRouteName="SplashLogo" screenOptions={{ headerShown: false }}>
          <Stack.Screen name="SplashLogo" component={SplashLogoScreen} />
          <Stack.Screen name="Inicio" component={TelaInicio} />
          <Stack.Screen name="CriarEscala" component={TelaCriarEscala} />
          <Stack.Screen name="Escalas" component={TelaListaEscalas} />
          <Stack.Screen name="DetalhesEscala" component={TelaDetalhesEscala} />
          <Stack.Screen name="Repertorios" component={RepertoiresScreen} />
          <Stack.Screen name="AdicionarRepertorio" component={AdicionarRepertorio} />
          <Stack.Screen name="DetalheRepertorio" component={DetalheRepertorio} />
          <Stack.Screen name="VisualizarArquivo" component={VisualizarArquivo} />
          <Stack.Screen name="Presenca" component={PresencaScreen} />
          <Stack.Screen name="Avisos" component={AvisosScreen} options={{ title: 'Avisos' }} />
          <Stack.Screen name="Ensaios" component={EnsaiosScreen} options={{ title: 'Ensaios' }} />
          <Stack.Screen name="Aniversariantes" component={TelaAniversariantes} options={{ title: 'Aniversariantes' }} />
          <Stack.Screen name="Agenda" component={TelaAgenda} options={{ title: 'Agenda' }} />
        </Stack.Navigator>
      </View>

      {/* Barra só aparece após o Splash */}
      <BarraNavegacaoFixa />
    </View>
  );
}

const estilos = StyleSheet.create({
  containerPrincipal: {
    flex: 1,
    backgroundColor: COR_FUNDO,
  },
  areaConteudo: {
    flex: 1,
    paddingBottom: 95, // Espaço para não cobrir conteúdo
  },
  barraContainer: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    alignItems: 'center',
    zIndex: 9999,
  },
  barraFundo: {
    width: LARGURA_TELA - 32,
    height: 75,
    backgroundColor: '#F3F4F6',
    borderTopLeftRadius: 24,
    borderTopRightRadius: 24,
    borderBottomLeftRadius: 16,
    borderBottomRightRadius: 16,
    flexDirection: 'row',
    justifyContent: 'space-around',
    alignItems: 'flex-end',
    paddingBottom: 10,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -4 },
    shadowOpacity: 0.15,
    shadowRadius: 12,
    elevation: 20,
    position: 'relative',
  },
  recorteCentral: {
    position: 'absolute',
    top: -22,
    left: '50%',
    transform: [{ translateX: -32 }],
    width: 64,
    height: 64,
    borderRadius: 32,
    backgroundColor: '#F3F4F6',
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: COR_DESTAQUE,
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.3,
    shadowRadius: 8,
  },
  botaoCentral: {
    width: 52,
    height: 52,
    borderRadius: 26,
    alignItems: 'center',
    justifyContent: 'center',
  },
  itemLateral: {
    alignItems: 'center',
    justifyContent: 'center',
    flex: 1,
  },
  iconeLateral: {
    marginBottom: 2,
  },
  rotuloLateral: {
    fontSize: 11,
    fontWeight: '500',
  },
});